SELECT id, 'aerated_settling_pond', '{"pretreatment":"aerated_settling_pond"}'::jsonb, NULL, 'Belüfteter Absetzteich: ≥ 1,2 m³/P = 1 200 l/P (§4.2.7)', 4, '{"v_min_l_p":1200,"v_min_l":null,"hrt_min_h":null,"a_spez_min_m2_p":null,"note":null}'::jsonb, 'The volume of the aerated settling pond, including the sludge storage but excluding the retention volume for stormwater treatment, must be at least $1.2 \mathrm{~m}^{3} / \mathrm{P}$. The stormwater treatment volume must be determined on the basis of Standard ATV-A 128. For combined sewer networks, the aerated settling ponds must be divided into a base volume for retention, pollutant degradation, and sludge storage, and a retention volume for storage of stormwater runoff.' FROM regulation_tables WHERE standard_code = 'DWA-A-262E' AND edition = '2017-11' AND table_code = 'S4_2_VORBEHANDLUNG'
